using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BuildBowlReturnChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var p=new BuildBowlProject();Check(p.Valid()&&!p.RecordReturn(0),"Legacy/empty return invalid");p.Begin(1,0);p.Confirm(true,false,1,true,false);Check(p.RecordReturn(1)&&!p.RecordReturn(1)&&p.returns==1&&p.Valid(),"Return duplicated");p.Confirm(false,true,2,true,false);Check(p.RecordReturn(2)&&p.returns==2&&p.Valid(),"Final shot cannot be returned");Check(JsonUtility.FromJson<BuildBowlProject>(JsonUtility.ToJson(p)).Valid(),"Return history failed to save");p.Begin(1,3);Check(p.returns==0&&p.lastReturnedShot==0&&!p.RecordReturn(1),"New attempt retained old return");p.Confirm(false,false,4,true,false);p.End();Check(!p.RecordReturn(1),"Ended project received return");p.lastReturnedShot=2;Check(!p.Valid(),"Future return accepted");Debug.Log("BWVR_BUILD_BOWL_RETURN_MODEL_PASS: old saves, actual-shot prerequisite, duplicate guard, final-shot return, saved counters, replay/end boundaries and bounds");}
 public static void VerifyRuntime(Action<QuestSlice,BeachBall,ConstructionSite> afterReturn=null){BuildBowlChecks.VerifyRuntime((slice,ball,site)=>{
  var field=typeof(QuestSlice).GetField("state",F);var state=(SliceState)field.GetValue(slice);var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>();var item=ball.GetComponent<CarryItem>();var project=state.buildBowl;int ticket=ball.FetchTicket;Check(ball.BuildBowlReturnRequested&&ball.FetchReserved&&project.returns==0&&!ball.CompleteFetch(ticket),"Safe shot did not offer voluntary return / offered free completion");var destination=ball.FetchHome;Check(Vector3.Distance(destination,item.home)>nav.world.Scale,"Return destination is generic home");
  state.paused=true;var before=ball.Body.position;float time=state.Hybrid.time;ball.Advance(100,true);god.Tick(100);Check(ball.Body.position==before&&state.Hybrid.time==time&&ball.BuildBowlReturnRequested&&!ball.ClaimFetch(ticket)&&project.returns==0,"Pause consumed return invitation");state.paused=false;
  var clone=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state));field.SetValue(slice,clone);Check(!ball.BuildBowlReturnRequested&&!ball.FetchReady&&!ball.OwnsFetch(ticket),"Replaced season retained stale return ownership");field.SetValue(slice,state);
  Check(nav.world.Sample(ball.transform.position+site.transform.forward*nav.world.Scale*14,nav.profile,12,out var foot),"No retrieval approach");god.transform.position=nav.world.ProjectFoot(foot,nav.profile);god.transform.LookAt(ball.transform.position);nav.ResetRoute();Physics.SyncTransforms();state.hunger=0;state.playPreference=1;state.socialPreference=0;foreach(var t in god.Targets)if(t.affordance!=null)t.affordance.cooldown=t.GetComponent<BeachBall>()==ball?0:state.Hybrid.time+100000;
  int global=state.WorldPlay.fetchReturns;bool lifted=false,carried=false;for(int i=0;i<2400&&project.returns==0;i++){ball.Advance(.05f,false);god.Tick(.05f);lifted|=mind.Current==CreatureCuriosity.Phase.Lift;carried|=mind.Current==CreatureCuriosity.Phase.FetchCarry;}
  Check(lifted&&carried&&project.returns==1&&project.lastReturnedShot==1&&state.WorldPlay.fetchReturns==global+1&&!ball.BuildBowlReturnRequested&&!ball.FetchReserved&&!item.held&&Vector3.Distance(ball.transform.position,destination)<nav.world.Scale,"Native return failed: "+mind.Current+" / returns="+project.returns+" / reserved="+ball.FetchReserved+" / time="+state.Hybrid.time);Check(state.Hybrid.receipt.eligible&&state.Hybrid.receipt.fetched&&state.Hybrid.receipt.target==ball.StableId,"Real retrieval did not produce its existing fetched lesson");float fun=state.WorldPlay.fetchFun;Check(god.Feedback(true)&&!god.Feedback(true)&&state.WorldPlay.fetchFun>fun&&!ball.CompleteFetch(ticket),"Return teaching/duplicate completion failed");Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state)).Valid(),"Returned state invalid");afterReturn?.Invoke(slice,ball,site);Debug.Log("BWVR_BUILD_BOWL_RETURN_RUNTIME_PASS: real safe-shot invitation, different local shooting destination, no free completion, pause and stale-season guards, autonomous utility selection, native approach/lift/carry/place, one saved return, existing fetched receipt and one-shot teaching");
 });}
}
}
